def solve_game(N):
    # S[n] will store the status of position n: 1 if W (Winning), 0 if L (Losing)
    S = {}

    # We iterate backwards from N-1 down to 1
    # S[N] is the terminal winning state, but we only need to evaluate moves into it.

    # Initialize states for n > N/2, where only n+1 is a valid move
    for n in range(N - 1, N // 2, -1):
        # Only move is n+1.
        next_state = n + 1

        # If n+1 == N, the player wins immediately.
        if next_state == N:
            S[n] = 1  # W
        else:
            # Since S[n+1] must have been calculated in the previous iteration
            # If S[n+1] is L (0), then S[n] is W (1).
            # If S[n+1] is W (1), then S[n] is L (0).
            # This is equivalent to S[n] = 1 - S[n+1]
            S[n] = 1 - S[n+1]

    # Iterate for n <= N/2
    for n in range(N // 2, 0, -1):
        moves = []
        # Move 1: n+1
        moves.append(n + 1)

        # Move 2: 2n
        if 2 * n <= N:
            moves.append(2 * n)

        # Check if there is any move leading to a Losing position (S[m] == 0)
        can_win = False
        for m in moves:
            # Note: S[m] must have been calculated because m > n
            if S[m] == 0:
                can_win = True
                break

        if can_win:
            S[n] = 1  # W
        else:
            S[n] = 0  # L

    return S.get(1)

